// SSN Self-Contained Base64 Embedded Assets
const SSN_LOGO_URI = "data:image/png;base64,";
const SSN_CAMPUS_BG_URI = "data:image/jpeg;base64,";

function applyEmbeddedImages() {
  document.querySelectorAll('img.ssn-logo-img, img.about-ssn-logo, .fhp-avatar-img, img.hero-campus-logo-img').forEach(img => {
    img.src = SSN_LOGO_URI;
  });
  document.querySelectorAll('img.campus-hero-img, img.about-campus-img, .campus-img-view').forEach(img => {
    img.src = SSN_CAMPUS_BG_URI;
  });
  const favicon = document.querySelector('link[rel="icon"]');
  if (favicon) favicon.href = SSN_LOGO_URI;
  const hero = document.querySelector('.hero');
  if (hero) hero.style.backgroundImage = `linear-gradient(135deg, rgba(0, 24, 51, 0.40) 0%, rgba(0, 34, 68, 0.35) 50%, rgba(0, 56, 112, 0.40) 100%), url('')`;
  const aboutStrip = document.querySelector('.about-strip');
  if (aboutStrip) aboutStrip.style.backgroundImage = `linear-gradient(135deg, rgba(0, 34, 68, 0.88) 0%, rgba(0, 51, 102, 0.85) 100%), url('')`;
  const loginSb = document.querySelector('.login-sidebar');
  if (loginSb) loginSb.style.backgroundImage = `linear-gradient(180deg, rgba(0, 24, 51, 0.88) 0%, rgba(0, 34, 68, 0.90) 100%), url('')`;
}

document.addEventListener('DOMContentLoaded', applyEmbeddedImages);
if (document.readyState === 'interactive' || document.readyState === 'complete') { applyEmbeddedImages(); }
